{"type": "file", "encoding": "utf-8", "name": "NotificationManager.cs", "path": "Assets/Scripts/Notifications/NotificationManager.cs", "size": 21075, "sha": "7bcaf63bd1f4f1d3f1d5c368f0840d41dd22958e", "content": "﻿using System;
using System.Collections;
using UnityEngine;
using HarmonyLogging;
using Match3D.Utility;
using Match3D.Game.Levels;
using Utils;

#if UNITY_ANDROID
using Unity.Notifications.Android;
using UnityEngine.Android;
#elif UNITY_IOS
using Unity.Notifications.iOS;
#endif

namespace Notifications
{
    public class NotificationManager : MonoBehaviour
    {
        public static NotificationManager Instance { get; private set; }
        public bool NotificationsEnabled { get; private set; } = false; // Default to false
        private const string AndroidChannelId = "default_channel";
        private const string NotificationsEnabledKey = "NotificationsEnabled";
        public const string NotificationsPermission = "NotificationsPermission";
        public const string FirstNotificationsPermission = "FirstNotificationsPermission";
        private const string PermissionGranted = "PermissionGranted";
        private const string PermissionDenied = "PermissionDenied";

        private void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
                DontDestroyOnLoad(gameObject);
                // Load the notificationsEnabled flag from PlayerPrefs
                NotificationsEnabled = PlayerPrefs.GetInt(NotificationsEnabledKey, 0) == 1;
            }
            else
            {
                Destroy(gameObject);
            }
        }

        void OnEnable()
        {
#if UNITY_ANDROID
            AndroidNotificationCenter.OnNotificationReceived += OnNotificationReceived;
#elif UNITY_IOS
        iOSNotificationCenter.OnNotificationReceived += OnNotificationReceived;
#endif
        }

        void OnDisable()
        {
#if UNITY_ANDROID
            AndroidNotificationCenter.OnNotificationReceived -= OnNotificationReceived;
#elif UNITY_IOS
        iOSNotificationCenter.OnNotificationReceived -= OnNotificationReceived;
#endif
        }

#if UNITY_ANDROID
        private void OnNotificationReceived(AndroidNotificationIntentData data)
        {
        }
#endif

#if UNITY_IOS
    private void OnNotificationReceived(iOSNotification notification)
    {
    }
#endif

        public void Init()
        {
            InitializeNotifications();
        }

        private void OnApplicationFocus(bool focus)
        {
            if (focus)
            {
                // Check and update notification permission status
#if UNITY_ANDROID
                if (Permission.HasUserAuthorizedPermission("android.permission.POST_NOTIFICATIONS"))
                {
                    PlayerPrefs.SetString(NotificationsPermission, PermissionGranted);
                }
                else
                {
                    PlayerPrefs.SetString(NotificationsPermission, PermissionDenied);
                }
#elif UNITY_IOS
            var notificationSettings = iOSNotificationCenter.GetNotificationSettings();
            if (notificationSettings.AuthorizationStatus == AuthorizationStatus.Authorized)
            {
                PlayerPrefs.SetString(NotificationsPermission, PermissionGranted);
            }
            else
            {
                PlayerPrefs.SetString(NotificationsPermission, PermissionDenied);
            }
#endif
                // Clear notifications and check for any triggered by app focus
                ClearNotifications();
                CheckIfAppOpenedFromNotification();
            }
            else
            {
                ClearNotifications();
                ScheduleDominoNotifications();
            }
        }

        public void EnableNotifications()
        {
            NotificationsEnabled = true;
            PlayerPrefs.SetInt(NotificationsEnabledKey, 1);
            PlayerPrefs.Save();

            ClearNotifications();
            ScheduleDominoNotifications();
        }

        public void DisableNotifications()
        {
            NotificationsEnabled = false;
            PlayerPrefs.SetInt(NotificationsEnabledKey, 0);
            PlayerPrefs.Save();
            ClearNotifications();
        }

        private void ScheduleDominoNotifications()
        {
            if (!NotificationsEnabled /*|| PlayerData.Profile == null*/)
                return;

            DateTime serverToday = HarmonyTime.GetServerDateTime().Date;

            // Lives recharge
            string LivesRechargedTitle = "Full Ammo Reloaded! 🔫";
            string LivesRechargedMessage = "Your energy is fully charged! The zombies are closing in—jump back into the battle now and show them who's boss. 🧟⚔️";

            // Lapsed last session reminder
            string OneDayLapsedTitle = "The Horde Is Growing… 🧟‍♂️";
            string OneDayLapsedMessage = "The zombie outbreak won’t stop on its own! Return to Zombie Match 3D now and continue your mission. New challenges await! 🧠🔥";

            // Lapsed Weekly reminder batch
            string WeeklyReminderTitle = "They’ve Taken Over… Can You Stop Them? 😱";
            string WeeklyReminderMessage = "It’s been a while, survivor. The undead are stronger than ever. Rally your gear and get back into the fray before it’s too late! 🧟‍♀️💥";

            // Lapsed Weekly reminder batch
            string WeeklyLeaderboardTitle = "Weekly Rankings Reset! 🎯";
            string WeeklyLeaderboardMessage = "New week, fresh shot at glory! Climb the leaderboard and prove you’re the ultimate zombie slayer. Ready to dominate? 🏙️🧟";

            // Finish first tutorial
            string FinishFirstTutorialTitle = "Finish Your First Mission! 🧟‍♀️📈";
            string FinishFirstTutoriaMessage = "You’re so close! Complete your first mission in Zombie Match 3D and unlock powerful tools to fight the undead. The city needs you! 💪";

            // Plague Race Event
            string PlagueRaceTitle = "Plague Race Is On! 🌊🚣";
            string PlagueRaceMessage = "Compete in Plague Race now! Speed through levels, outmatch rivals, and claim your place on the leaderboard before time runs out. ⚡🏆";

            // Schedule lives regen notification
            ScheduleLivesRechargedNotification(LivesRechargedTitle, LivesRechargedMessage, serverToday);

            // Schedule Finish first tutorial
            ScheduleFinishFirstTutorialNotification(FinishFirstTutorialTitle, FinishFirstTutoriaMessage, serverToday);

            // Schedule Lapsed last session reminder
            DailyNotifications(OneDayLapsedTitle, OneDayLapsedMessage, serverToday);

            // Schedule Weekly reminder batch
            BatchScheduleWeeklyNotifications(WeeklyReminderTitle, WeeklyReminderMessage, 4, serverToday);

            // Schedule Weekly Leaderboard reminder batch
            BatchScheduleWeeklyLeaderboardNotifications(WeeklyLeaderboardTitle, WeeklyLeaderboardMessage, 4, serverToday);

            // Schedule Events
            BatchSchedulePlagueRace(PlagueRaceTitle, PlagueRaceMessage, 5, serverToday);
        }

        private void ScheduleLivesRechargedNotification(string title, string message, DateTime serverToday)
        {
            if (LivesManager.IsInfiniteLivesActive)
            {
                return;
            }

            if (LivesManager.Instance != null && LivesManager.Instance.Lives < LivesManager.MaxLives)
            {
                var livesToRecharge = LivesManager.MaxLives - LivesManager.Instance.Lives;
                var lastRewardTime = LivesManager.Instance.GetRegenerationTime();
                TimeSpan timeSinceLastReward = DateTime.UtcNow - lastRewardTime;
                float nextLifeTimeRemaining = (float)LivesManager.RegenTime.TotalSeconds - (float)timeSinceLastReward.TotalSeconds;
                float allLivesTimeRemaining = nextLifeTimeRemaining + (livesToRecharge - 1) * (float)LivesManager.RegenTime.TotalSeconds;
                if (allLivesTimeRemaining > 0)
                {
                    ScheduleNotification(title, message, DateTime.Now.AddSeconds(allLivesTimeRemaining));
                }
            }
        }

        private void ScheduleFinishFirstTutorialNotification(string title, string message, DateTime serverToday)
        {
            if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() < LevelVariantManager.FirstTutorialFinished)
            {
                DateTime date = serverToday.AddHours(12);
                ScheduleNotification(title, message, date);
            }
        }

        private void DailyNotifications(string title, string message, DateTime serverToday)
        {
            DateTime date = serverToday.AddDays(1);
            ScheduleNotification(title, message, date);
        }

        private void BatchScheduleWeeklyNotifications(string title, string message, int weeksToCover, DateTime referenceDate)
        {
            for (int i = 1; i <= weeksToCover; i++)
            {
                DateTime fireTime = referenceDate.AddDays(i * 7);
                ScheduleNotification(title, message, fireTime);
            }
        }

        private void BatchSchedulePlagueRace(string title, string message, int daysToCover, DateTime serverToday)
        {
            if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() >= LevelVariantManager.PlagueRaceUnlockLevel)
            {
                for (int i = 1; i <= daysToCover; i++)
                {
                    DateTime date = serverToday.AddDays(i);
                    DateTime fireTime = date.AddMinutes(15);
                    ScheduleNotification(title, message, fireTime);
                }
            }
        }

        private void BatchScheduleWeeklyLeaderboardNotifications(string title, string message, int weeksToCover, DateTime referenceDate)
        {
            if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() >= LevelVariantManager.LeaderboardsUnlockLevel)
            {
                for (int i = 1; i <= weeksToCover; i++)
                {
                    DateTime fireTime = referenceDate.AddDays(i * 7);
                    ScheduleNotification(title, message, fireTime);
                }
            }
        }

        private void ClearNotifications()
        {
#if UNITY_ANDROID
            AndroidNotificationCenter.CancelAllNotifications();
#elif UNITY_IOS
        iOSNotificationCenter.RemoveAllScheduledNotifications();
        iOSNotificationCenter.RemoveAllDeliveredNotifications();
#endif
        }

        void CheckIfAppOpenedFromNotification()
        {
#if UNITY_ANDROID
            var lastNotificationIntent = AndroidNotificationCenter.GetLastNotificationIntent();
            if (lastNotificationIntent != null)
            {
                // App was opened from a notification
                HL.Log(HC.Notification, "App opened from notification with title: " + lastNotificationIntent.Notification.Title);
                if (AnalyticsManager.Instance != null)
                {
                    AnalyticsManager.Instance.TrackStartedFromNotification(lastNotificationIntent.Notification.Title);
                }
            }
#elif UNITY_IOS
        var lastNotification = iOSNotificationCenter.GetLastRespondedNotification();
        if (lastNotification != null)
        {
            // App was opened from a notification
            HL.Log(HC.Notification, "App opened from notification with title: " + lastNotification.Title);
            if (AnalyticsManager.Instance != null)
            {
                AnalyticsManager.Instance.TrackStartedFromNotification(lastNotification.Title);
            }
        }
#endif
        }

        private void InitializeNotifications()
        {
            if (PlayerPrefs.HasKey(FirstNotificationsPermission))
            {
                HL.Log(HC.Notification, "Notification permission already requested once.");
                return;
            }
#if UNITY_ANDROID
            StartCoroutine(RequestAndroidNotificationPermission());
#elif UNITY_IOS
        StartAuthorizationProcess();
#endif
        }

#if UNITY_ANDROID
        private IEnumerator RequestAndroidNotificationPermission()
        {
            HL.Log(HC.Notification, "Starting notification permission request");
            yield return new WaitForSeconds(1f); // Delay to ensure Unity and Android runtime are initialized

            var permission = "android.permission.POST_NOTIFICATIONS";
            HL.Log(HC.Notification, $"Current permission status: {Permission.HasUserAuthorizedPermission(permission)}");

            if (Permission.HasUserAuthorizedPermission(permission))
            {
                EnableNotifications();
                RegisterNotificationChannel();
                yield break;
            }

            // Optional: Show UI prompt explaining why notifications are needed
            // ShowNotificationPromptUI(() => { /* Proceed with permission request */ });
            bool permissionProcessed = false;
            var callbacks = new PermissionCallbacks();
            callbacks.PermissionGranted += (permissionName) =>
            {
                permissionProcessed = true;
                if (UnityMainThreadDispatcher.Instance != null)
                {
                    UnityMainThreadDispatcher.Instance.Enqueue(() =>
                    {
                        HandlePermissionResponse(true, permissionName, "Permission granted: ");
                    });
                }
                else
                {
                    HandlePermissionResponse(true, permissionName, "Permission granted: ");
                };
            };
            callbacks.PermissionDenied += (permissionName) =>
            {
                permissionProcessed = true;
                if (UnityMainThreadDispatcher.Instance != null)
                {
                    UnityMainThreadDispatcher.Instance.Enqueue(() =>
                    {
                        HandlePermissionResponse(false, permissionName, "Permission denied: ");
                    });
                }
                else
                {
                    HandlePermissionResponse(false, permissionName, "Permission denied: ");
                };
            };
            callbacks.PermissionDeniedAndDontAskAgain += (permissionName) =>
            {
                permissionProcessed = true;
                if (UnityMainThreadDispatcher.Instance != null)
                {
                    UnityMainThreadDispatcher.Instance.Enqueue(() =>
                    {
                        HandlePermissionResponse(false, permissionName, "Permission denied and don't ask again: ");
                    });
                }
                else
                {
                    HandlePermissionResponse(false, permissionName, "Permission denied and don't ask again: ");
                };
            };

            Permission.RequestUserPermission(permission, callbacks);
            float timeout = 10f; // Timeout after 10 seconds
            float elapsed = 0f;
            while (!permissionProcessed && elapsed < timeout)
            {
                elapsed += Time.deltaTime;
                yield return null;
            }
            if (elapsed >= timeout)
            {
                HL.Log(HC.Notification, "Permission request timed out");
                DisableNotifications();
            }
        }

        private void HandlePermissionResponse(bool granted, string permissionName, string logMessage)
        {
            if (AnalyticsManager.Instance != null)
            {
                AnalyticsManager.Instance.TrackNotificationsPermission(granted);
            }

            if (granted)
            {
                EnableNotifications();
                RegisterNotificationChannel();
            }
            else
            {
                DisableNotifications();
            }

            HL.Log(HC.Notification, logMessage + permissionName);
            PlayerPrefs.SetString(NotificationsPermission, granted ? PermissionGranted : PermissionDenied);
            PlayerPrefs.SetString(FirstNotificationsPermission, "FirstNotificationsPermission");
            PlayerPrefs.Save();
        }


        private void RegisterNotificationChannel()
        {
            var androidChannel = new AndroidNotificationChannel()
            {
                Id = "default_channel",
                Name = "Default Channel",
                Importance = Importance.Default,
                Description = "Generic notifications",
            };
            AndroidNotificationCenter.RegisterNotificationChannel(androidChannel);
        }
#endif

        // Optional: Implement this method based on your UI system
        private void ShowNotificationPromptUI(Action onProceed)
        {
            // Example: Show a UI popup with "Allow Notifications?" and "OK" button
            HL.Log(HC.Notification, "Showing notification permission prompt");
            // Replace with your actual UI system (e.g., Unity UI, Canvas)
            onProceed?.Invoke();
        }

#if UNITY_IOS
    private IEnumerator RequestAuthorization(Action<bool> onGranted)
    {
        var authorizationOption = AuthorizationOption.Alert | AuthorizationOption.Badge;
        using (var req = new AuthorizationRequest(authorizationOption, true))
        {
            while (!req.IsFinished)
            {
                yield return null;
            }

            string res = "\n RequestAuthorization:";
            res += "\n finished: " + req.IsFinished;
            res += "\n granted :  " + req.Granted;
            res += "\n error:  " + req.Error;
            res += "\n deviceToken:  " + req.DeviceToken;
            HL.Log(HC.Notification, res);
            onGranted(req.Granted);
        }
    }

    void StartAuthorizationProcess()
    {
        StartCoroutine(RequestAuthorization(granted =>
        {
            HandleAuthorizationGranted(granted);
        }));
    }

    void HandleAuthorizationGranted(bool granted)
    {
        if (AnalyticsManager.Instance != null)
        {
            AnalyticsManager.Instance.TrackNotificationsPermission(granted);
        }
        if (granted)
        {
            HL.Log(HC.Notification, "Notification permission granted");
            PlayerPrefs.SetString(NotificationsPermission, PermissionGranted);
            PlayerPrefs.SetString(FirstNotificationsPermission, "FirstNotificationsPermission");
            EnableNotifications();
        }
        else
        {
            HL.Log(HC.Notification, "Notification permission denied");
            PlayerPrefs.SetString(NotificationsPermission, PermissionDenied);
            PlayerPrefs.SetString(FirstNotificationsPermission, "FirstNotificationsPermission");
            DisableNotifications();
        }
    }
#endif

        private void ScheduleNotification(string title, string message, DateTime fireTime)
        {
            if (fireTime <= DateTime.Now)
            {
                HL.Log(HC.Notification, $"Attempted to schedule notification in the past: {title} at {fireTime}");
                return;
            }
#if UNITY_ANDROID
            var notif = new AndroidNotification
            {
                Title = title,
                Text = message,
                FireTime = fireTime,
            };
            AndroidNotificationCenter.SendNotification(notif, AndroidChannelId);
#elif UNITY_IOS
        var notification = new iOSNotification
        {
            Title = title,
            Body = message,
            ShowInForeground = true,
            ForegroundPresentationOption = (PresentationOption.Alert | PresentationOption.Sound),
            CategoryIdentifier = "category_a",
            ThreadIdentifier = "thread1",
            Trigger = new iOSNotificationCalendarTrigger
            {
                Year = fireTime.Year,
                Month = fireTime.Month,
                Day = fireTime.Day,
                Hour = fireTime.Hour,
                Minute = fireTime.Minute,
                Second = fireTime.Second,
                Repeats = false
            }
        };
        iOSNotificationCenter.ScheduleNotification(notification);
#endif
        }

        public void RequestNotificationPermission()
        {
#if UNITY_ANDROID

            AndroidJavaClass unityPlayer = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject currentActivity = unityPlayer.GetStatic<AndroidJavaObject>("currentActivity");
            AndroidJavaObject intent = new AndroidJavaObject("android.content.Intent", "android.settings.APPLICATION_DETAILS_SETTINGS");
            AndroidJavaObject uri = new AndroidJavaClass("android.net.Uri").CallStatic<AndroidJavaObject>("fromParts", "package", Application.identifier, null);
            intent.Call<AndroidJavaObject>("setData", uri);
            currentActivity.Call("startActivity", intent);
#elif UNITY_IOS
            Application.OpenURL("app-settings:");
#endif
        }

    }
}
